require_once __DIR__.'/_common.php';$current_slug='data-anak';require_once ROOT_PATH.'/includes/auth-guard.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$anak=$id?data_anak_get($id):null;if(!$anak){set_flash('warning','Data anak tidak ditemukan.');redirect(data_anak_url());}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token()){set_flash('danger','Token keamanan tidak valid.');redirect(data_anak_url('hapus.php',['id'=>$id]));}
 try{$pdo->beginTransaction();$oid=(int)$anak['id_orangtua'];$q=$pdo->prepare('SELECT id_pengukuran FROM pengukuran WHERE id_anak=?');$q->execute([$id]);$measurements=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));if($measurements){$marks=implode(',',array_fill(0,count($measurements),'?'));$q=$pdo->prepare("SELECT id_pemantauan FROM pemantauan WHERE id_anak=?");$q->execute([$id]);$monitor=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));if($monitor){$m=implode(',',array_fill(0,count($monitor),'?'));$pdo->prepare("DELETE FROM catatan_intervensi WHERE id_pemantauan IN ($m)")->execute($monitor);}$pdo->prepare('DELETE FROM pemantauan WHERE id_anak=?')->execute([$id]);$pdo->prepare("DELETE FROM status_gizi WHERE id_pengukuran IN ($marks)")->execute($measurements);$pdo->prepare("DELETE FROM pengukuran WHERE id_anak=?")->execute([$id]);}
 $pdo->prepare('DELETE FROM kehadiran WHERE id_anak=?')->execute([$id]);$pdo->prepare('DELETE FROM anak WHERE id_anak=?')->execute([$id]);$q=$pdo->prepare('SELECT COUNT(*) FROM anak WHERE id_orangtua=?');$q->execute([$oid]);if(!(int)$q->fetchColumn())$pdo->prepare('DELETE FROM orangtua WHERE id_orangtua=?')->execute([$oid]);$pdo->commit();set_flash('success','Data anak dan riwayat terkait berhasil dihapus.');redirect(data_anak_url());}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger','Data anak belum dapat dihapus karena masih terhubung dengan data lain.');redirect(data_anak_url('detail.php',['id'=>$id]));}}
